'use client';

import { useState } from 'react';

import { MorphingLabel } from '@/registry/ndeko/components/navbar/_parts/morphing-label';
import { CalendarIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Calendar } from '@/registry/ndeko/ui/calendar';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

type DateRange = { from: Date | undefined; to?: Date | undefined };

const DATE_FORMAT = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
});

function rangeLabelOf(range: DateRange | undefined) {
  const from = range?.from;
  if (!from) {
    return 'Date';
  }
  const to = range?.to;
  if (!to) {
    return DATE_FORMAT.format(from);
  }
  return DATE_FORMAT.formatRange(from, to);
}

function DatePicker() {
  const [range, setRange] = useState<DateRange | undefined>();
  const label = rangeLabelOf(range);

  function selectRange(nextRange: DateRange | undefined) {
    setRange(nextRange);
  }

  return (
    <Popover>
      <PopoverTrigger
        render={<Button variant='outline' className='tabular-nums' />}
      >
        <CalendarIcon className='text-muted-foreground' />
        <MorphingLabel value={label}>{label}</MorphingLabel>
      </PopoverTrigger>
      <PopoverContent align='start' className='w-auto p-2'>
        <Calendar mode='range' selected={range} onSelect={selectRange} />
      </PopoverContent>
    </Popover>
  );
}

export { DatePicker };

'use client';

import { useState } from 'react';

import { ListFilterIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { Label } from '@/registry/ndeko/ui/label';
import {
  Popover,
  PopoverClose,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

const WIDGETS = [
  { value: 'real-time', label: 'Real time' },
  { value: 'top-channels', label: 'Top channels' },
  { value: 'last-orders', label: 'Last orders' },
  { value: 'total-spent', label: 'Total spent' },
];

function Filters() {
  const [shownWidgets, setShownWidgets] = useState<string[]>([]);
  const hasSelection = shownWidgets.length > 0;

  function toggleWidget(value: string, isChecked: boolean) {
    setShownWidgets((current) => {
      const others = current.filter((widget) => widget !== value);
      if (isChecked) {
        return [...others, value];
      }
      return others;
    });
  }

  function clearWidgets() {
    setShownWidgets([]);
  }

  return (
    <Popover>
      <PopoverTrigger render={<Button variant='outline' />}>
        <ListFilterIcon className='text-muted-foreground' />
        Filters
      </PopoverTrigger>
      <PopoverContent align='end' className='flex w-44 flex-col gap-3 p-3'>
        <PopoverTitle className='text-muted-foreground text-xs'>
          Filters
        </PopoverTitle>
        <div className='flex flex-col gap-3'>
          {WIDGETS.map((widget) => {
            const isChecked = shownWidgets.includes(widget.value);

            return (
              <Label key={widget.value} className='font-normal'>
                <Checkbox
                  checked={isChecked}
                  onCheckedChange={(checked) =>
                    toggleWidget(widget.value, checked)
                  }
                />
                {widget.label}
              </Label>
            );
          })}
        </div>
        <div className='flex justify-between gap-2 pt-1'>
          <Button
            variant='outline'
            size='sm'
            onClick={clearWidgets}
            disabled={!hasSelection}
            focusableWhenDisabled
          >
            Clear
          </Button>
          <PopoverClose render={<Button size='sm' />}>Apply</PopoverClose>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export { Filters };

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const LABEL_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)', transition: EXIT_TRANSITION },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

function labelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return LABEL_VARIANTS;
}

type MorphingLabelProps = {
  value: string;
  className?: string;
  children: React.ReactNode;
};

function MorphingLabel({ value, className, children }: MorphingLabelProps) {
  const shouldReduceMotion = useReducedMotion();
  const labelVariants = labelVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          className={cn('flex whitespace-nowrap', className)}
          variants={labelVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

export { MorphingLabel };
